import * as THREE from 'three';

const $=s=>document.querySelector(s), canvas=$('#world');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9ca99e); scene.fog=new THREE.FogExp2(0x9ca99e,.0082);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,260);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1;
scene.add(new THREE.HemisphereLight(0xc9d8db,0x35312b,2.1));
const sun=new THREE.DirectionalLight(0xffd5a0,3.2); sun.position.set(-35,55,18); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-75;sun.shadow.camera.right=75;sun.shadow.camera.top=75;sun.shadow.camera.bottom=-75;sun.shadow.bias=-.0002;scene.add(sun);
const fill=new THREE.DirectionalLight(0x9bc4ca,.8); fill.position.set(45,28,-35);scene.add(fill);
const mats={}; const mat=(c,r=.92,m=0)=>new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:m});
mats.grass=mat(0x71816c);mats.path=mat(0x88785f);mats.stone=mat(0x777b70);mats.darkStone=mat(0x464d49);mats.bark=mat(0x51483c);mats.leaf=mat(0x3e5a4a);mats.leaf2=mat(0x607352);mats.gold=mat(0xd8ad68,.32,.5);mats.glow=new THREE.MeshBasicMaterial({color:0x9bf2df});mats.armor=mat(0x343d3c,.55,.35);mats.cloth=mat(0x293d3b);mats.skin=mat(0xd4ad87);mats.blade=mat(0xc7d2c1,.28,.8);mats.enemy=mat(0x333d3d,.6,.35);mats.red=mat(0xc56b53,.4,.2);
const world=new THREE.Group();scene.add(world); let seed=8731;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function height(x,z){return .7+1.6*Math.sin(x*.075)*Math.cos(z*.062)+.85*Math.sin((x+z)*.12)+.48*Math.cos(x*.24-z*.17)+Math.max(0,Math.sin((x-z)*.08))*1.1}
function addMesh(parent,geo,material,pos,scale,cast=true){const o=new THREE.Mesh(geo,material);o.position.set(...pos);if(scale)o.scale.set(...scale);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
function terrain(){const n=120,size=160,verts=[],uv=[],idx=[];for(let j=0;j<=n;j++)for(let i=0;i<=n;i++){const x=(i/n-.5)*size,z=(j/n-.5)*size;verts.push(x,height(x,z),z);uv.push(i/n*18,j/n*18)}for(let j=0;j<n;j++)for(let i=0;i<n;i++){let a=j*(n+1)+i,b=a+1,c=a+n+1,d=c+1;idx.push(a,c,b,b,c,d)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();let m=new THREE.MeshStandardMaterial({color:0x809078,roughness:1});const mesh=new THREE.Mesh(g,m);mesh.receiveShadow=true;world.add(mesh);const water=addMesh(world,new THREE.PlaneGeometry(340,340),new THREE.MeshStandardMaterial({color:0x4c777a,roughness:.27,metalness:.15,transparent:true,opacity:.85}),[0,-1.7,0],null,false);water.rotation.x=-Math.PI/2;}
terrain();
const pathMat=new THREE.MeshStandardMaterial({color:0x9a896c,roughness:1});function path(points,width){const curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,height(x,z)+.035,z)));const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,Math.max(70,points.length*16),width,5,false),pathMat);mesh.scale.y=.035;mesh.receiveShadow=true;world.add(mesh)}path([[0,28],[4,20],[2,12],[-4,3],[-1,-6],[5,-17],[0,-31]],2.25);path([[0,11],[-12,10],[-24,7],[-34,5]],1.5);path([[0,9],[12,10],[25,7],[34,4]],1.5);
// Coastal cliffs, standing stones, and a ruined waystation
function rock(x,z,s=1){let o=addMesh(world,new THREE.DodecahedronGeometry(1,0),mats.stone,[x,height(x,z)+s*.35,z],[s*1.1,s*.8,s],true);o.rotation.set(rand(),rand()*3,rand());return o}
for(let i=0;i<100;i++){let a=rand()*Math.PI*2,r=62+rand()*12,x=Math.cos(a)*r,z=Math.sin(a)*r;rock(x,z,2+rand()*5)}
function tree(x,z,s=1){const y=height(x,z);const group=new THREE.Group();group.position.set(x,y,z);world.add(group);addMesh(group,new THREE.CylinderGeometry(.13*s,.3*s,2.8*s,6),mats.bark,[0,1.35*s,0],[1,1,1]);for(let k=0;k<3;k++){const cone=addMesh(group,new THREE.ConeGeometry((1.45-k*.27)*s,(2.3-k*.12)*s,7),k===1?mats.leaf2:mats.leaf,[0,(2.15+k*.8)*s,0],[1,1,1]);cone.rotation.y=rand()*3}return group}
for(let i=0;i<115;i++){let x=(rand()-.5)*135,z=(rand()-.5)*135;if(Math.hypot(x,z)<13||Math.abs(x)<6&&z>-34&&z<31||Math.abs(z-8)<4&&Math.abs(x)<36)continue;tree(x,z,.65+rand()*.85)}
for(let i=0;i<65;i++){let x=(rand()-.5)*125,z=(rand()-.5)*125;if(Math.hypot(x,z)<10)continue;rock(x,z,.35+rand()*.9)}
function ruins(x,z){const g=new THREE.Group();g.position.set(x,height(x,z),z);world.add(g);let base=addMesh(g,new THREE.CylinderGeometry(4,4.4,.6,12),mats.darkStone,[0,.25,0],[1,1,1]);for(let i=0;i<5;i++){let a=i*Math.PI*2/5;let p=addMesh(g,new THREE.BoxGeometry(.8,4,.8),mats.stone,[Math.cos(a)*3,2.2,Math.sin(a)*3],[1,1,1]);p.rotation.y=-a;addMesh(g,new THREE.BoxGeometry(1.7,.35,1.1),mats.darkStone,[Math.cos(a)*3,4.25,Math.sin(a)*3],[1,1,1])}return g}
ruins(-28,7);ruins(28,7);ruins(0,-31);
// lanterns on the old road
function lantern(x,z){let y=height(x,z);addMesh(world,new THREE.CylinderGeometry(.08,.15,2.3,6),mats.darkStone,[x,y+1.15,z]);const flame=new THREE.PointLight(0xe4a766,1.3,9,2);flame.position.set(x,y+2.35,z);world.add(flame);addMesh(world,new THREE.SphereGeometry(.14,8,6),new THREE.MeshBasicMaterial({color:0xffc778}),[x,y+2.35,z],null,false)}for(const [x,z] of [[-6,20],[6,17],[-4,6],[4,-6],[1,-19]])lantern(x,z);
// Beacon at the heart of Hollowwind
const beacon=new THREE.Group();beacon.position.set(0,height(0,0),0);world.add(beacon);addMesh(beacon,new THREE.CylinderGeometry(2.4,3.2,1.2,8),mats.darkStone,[0,.5,0]);addMesh(beacon,new THREE.CylinderGeometry(.55,.9,3.2,8),mats.stone,[0,2.2,0]);const beaconRing=addMesh(beacon,new THREE.TorusGeometry(2.15,.12,8,32),mats.gold,[0,3.15,0]);beaconRing.rotation.x=Math.PI/2;const beaconCrystal=addMesh(beacon,new THREE.OctahedronGeometry(.8),mats.glow,[0,3.4,0],[1,1.5,1],false);const beaconLight=new THREE.PointLight(0x76d9cb,0,24,2);beaconLight.position.set(0,4,0);beacon.add(beaconLight);
// Shards glow at the three forgotten shrines
const shards=[];for(const [x,z] of [[-28,7],[28,7],[0,-31]]){const g=new THREE.Group();g.position.set(x,height(x,z)+1.5,z);world.add(g);const crystal=addMesh(g,new THREE.OctahedronGeometry(.52),mats.glow,[0,0,0],[.7,1.4,.7],false);const halo=addMesh(g,new THREE.TorusGeometry(.78,.025,6,36),mats.gold,[0,-.55,0],[1,1,1],false);halo.rotation.x=Math.PI/2;const light=new THREE.PointLight(0x73eed9,1.25,10,2);g.add(light);shards.push({group:g,x,z,got:false})}

