const shards=[];for(const [x,z] of [[-28,7],[28,7],[0,-31]]){const g=new THREE.Group();g.position.set(x,height(x,z)+1.5,z);world.add(g);const crystal=addMesh(g,new THREE.OctahedronGeometry(.52),mats.glow,[0,0,0],[.7,1.4,.7],false);const halo=addMesh(g,new THREE.TorusGeometry(.78,.025,6,36),mats.gold,[0,-.55,0],[1,1,1],false);halo.rotation.x=Math.PI/2;const light=new THREE.PointLight(0x73eed9,1.25,10,2);g.add(light);shards.push({group:g,x,z,got:false})}

// Vale, the last coastwarden
function makeHero(){const g=new THREE.Group();const cloak=addMesh(g,new THREE.ConeGeometry(.68,1.45,7),mats.cloth,[0,1.0,.04]);cloak.rotation.x=Math.PI;const torso=addMesh(g,new THREE.CapsuleGeometry(.34,.62,4,8),mats.armor,[0,1.35,0]);const belt=addMesh(g,new THREE.TorusGeometry(.34,.055,6,12),mats.gold,[0,1.05,0]);belt.rotation.x=Math.PI/2;addMesh(g,new THREE.SphereGeometry(.25,10,8),mats.skin,[0,2.03,0]);const hood=addMesh(g,new THREE.SphereGeometry(.27,8,7),mats.cloth,[0,2.14,-.07],[1,.8,1]);hood.rotation.x=-.25;addMesh(g,new THREE.BoxGeometry(.37,.08,.28),mats.gold,[0,1.84,.12]);
for(const side of [-1,1]){addMesh(g,new THREE.CapsuleGeometry(.12,.45,3,6),mats.armor,[side*.43,1.37,0]).rotation.z=side*.15;addMesh(g,new THREE.CapsuleGeometry(.14,.55,3,6),mats.armor,[side*.19,.45,0]);addMesh(g,new THREE.CapsuleGeometry(.12,.4,3,6),mats.cloth,[side*.42,1.12,0]).rotation.z=side*.22}
const sword=new THREE.Group();sword.position.set(.56,1.25,.04);g.add(sword);addMesh(sword,new THREE.BoxGeometry(.09,.95,.13),mats.blade,[0,.48,0]);addMesh(sword,new THREE.BoxGeometry(.38,.09,.16),mats.gold,[0,.05,0]);addMesh(sword,new THREE.CylinderGeometry(.055,.055,.28,6),mats.bark,[0,-.12,0]);g.userData.sword=sword;world.add(g);return g}
const hero=makeHero();const player={x:0,z:25,hp:100,stamina:100,attack:0,dodge:0,invuln:0,face:Math.PI,dead:false};hero.position.set(player.x,height(player.x,player.z),player.z);
// An old wayfarer waits beside the road, cloaked in the fading light.
const npc=new THREE.Group();npc.position.set(-4,height(-4,26),26);world.add(npc);addMesh(npc,new THREE.CapsuleGeometry(.31,.67,4,8),mats.cloth,[0,1.15,0]);addMesh(npc,new THREE.SphereGeometry(.22,8,6),mats.skin,[0,1.87,0]);addMesh(npc,new THREE.ConeGeometry(.34,.48,7),mats.darkStone,[0,2.18,0]);const npcLantern=addMesh(npc,new THREE.SphereGeometry(.15),new THREE.MeshBasicMaterial({color:0xffc874}),[.5,.9,.1],null,false);const npcLight=new THREE.PointLight(0xffbf70,1.1,7);npcLight.position.set(.5,.9,.1);npc.add(npcLight);
function makeEnemy(x,z,boss=false){const g=new THREE.Group();g.position.set(x,height(x,z),z);world.add(g);addMesh(g,new THREE.CapsuleGeometry(boss?.52:.36,boss?1.05:.65,4,8),mats.enemy,[0,boss?1.12:.9,0]);addMesh(g,new THREE.SphereGeometry(boss?.4:.27,9,7),mats.darkStone,[0,boss?2.08:1.75,0]);addMesh(g,new THREE.ConeGeometry(boss?.48:.31,.52,6),mats.enemy,[0,boss?2.42:2.06,0]);for(const side of [-1,1]){const eye=addMesh(g,new THREE.SphereGeometry(boss?.085:.065,8,6),mats.red,[side*.13,boss?2.12:1.8,.24],null,false);const l=new THREE.PointLight(0xe94e3d,.45,2);l.position.copy(eye.position);g.add(l)}const weapon=new THREE.Group();weapon.position.set(.45,1.25,.05);g.add(weapon);addMesh(weapon,new THREE.BoxGeometry(.12,boss?1.5:1.05,.14),mats.darkStone,[0,.53,0]);addMesh(weapon,new THREE.BoxGeometry(.2,.25,.2),mats.red,[0,1.04,0]);return {group:g,x,z,hp:boss?240:65,max:boss?240:65,boss,alive:true,attack:0,hit:0,weapon}}
const enemies=[makeEnemy(-22,7),makeEnemy(22,7),makeEnemy(0,-25)];let boss=null;
const particles=[];function burst(x,y,z,color=0x9bf2df,count=18){for(let i=0;i<count;i++){const o=addMesh(world,new THREE.SphereGeometry(.045+rand()*.04,5,4),new THREE.MeshBasicMaterial({color,transparent:true}),[x,y,z],null,false);const v=new THREE.Vector3((rand()-.5)*5,1+rand()*5,(rand()-.5)*5);particles.push({mesh:o,v,life:.65+rand()*.55,max:1})}}
let memory=0,mode='title',dialogueLines=[],dialogueCallback=null,health=100,stamina=100,storyStarted=false,ending=false,toastTimer=0,noticeTimer=0,attackCooldown=0,invuln=0,cameraYaw=0,cameraPitch=.27,mouseDown=false,lastPointer={x:0,y:0},time=0,nearThing=null;
const keys={};
function toast(text){const el=$('#toast');el.textContent=text;el.classList.remove('hidden');el.style.animation='none';void el.offsetWidth;el.style.animation='fadeToast 3.2s forwards';toastTimer=3.2}
function notice(text){const el=$('#centerNotice');el.textContent=text;el.classList.remove('hidden');noticeTimer=2.8;setTimeout(()=>el.classList.add('hidden'),2800)}
function setQuest(title,text,progress){$('#questTitle').textContent=title;$('#questText').textContent=text;$('#questProgress').style.width=progress+'%';$('#shardCount').innerHTML='MEMORIES <b>'+memory+' / 3</b>';$('#distance').textContent=memory<3?'FOLLOW THE LIGHT':'RETURN TO THE BEACON'}
function showDialogue(lines,done){dialogueLines=lines;dialogueCallback=done;$('#dialogueText').textContent=dialogueLines.shift();$('#dialogue').classList.remove('hidden');mode='dialogue'}
function nextDialogue(){if(dialogueLines.length){$('#dialogueText').textContent=dialogueLines.shift();return}$('#dialogue').classList.add('hidden');if(dialogueCallback)dialogueCallback();dialogueCallback=null;if(mode==='dialogue')mode='play'}
$('#dialogueNext').addEventListener('click',nextDialogue);$('#dialogue').addEventListener('click',e=>{if(e.target.id!=='dialogueNext')nextDialogue()});
function startGame(){mode='play';$('#titleScreen').classList.add('hidden');$('#hud').classList.remove('hidden');$('#loading').classList.add('hidden');setQuest('A LIGHT IN THE DARK','Find the three lost memories. The beacon must be rekindled.',0);showDialogue(['The seventh winter came without a sunrise.','The beacon is dark. Its keepers are gone, and the coast has begun to forget its own name.','Find the memories they left behind, Vale. Then bring the light home.'],()=>{mode='play';storyStarted=true;toast('HOLLOWWIND REACH · THE SUNDERED COAST')})}
$('#beginBtn').addEventListener('click',startGame);$('#resumeBtn').addEventListener('click',()=>{mode='play';$('#pauseScreen').classList.add('hidden')});$('#pauseBtn').addEventListener('click',()=>{if(mode==='play'){mode='pause';$('#pauseScreen').classList.remove('hidden')}});$('#againBtn').addEventListener('click',()=>{$('#endingScreen').classList.add('hidden');mode='play';ending=true;toast('THE COAST IS YOURS TO EXPLORE')});

