function angleLerp(a,b,t){let d=((b-a+Math.PI)%(Math.PI*2)+Math.PI*2)%(Math.PI*2)-Math.PI;return a+d*t}
function updateEnemies(dt){for(const e of enemies.concat(boss?[boss]:[])){if(!e||!e.alive)continue;if(e.hit>0){e.hit-=dt;e.group.traverse(o=>{if(o.isMesh&&o.material===mats.enemy)o.material=mats.red});if(e.hit<=0)e.group.traverse(o=>{if(o.isMesh&&o.material===mats.red)o.material=mats.enemy})}const dx=player.x-e.x,dz=player.z-e.z,d=Math.hypot(dx,dz);if(d<(e.boss?24:16)){const desired=Math.atan2(dx,dz);e.group.rotation.y=angleLerp(e.group.rotation.y,desired,dt*4);if(d>(e.boss?3.5:2.1)){const sp=e.boss?2.45:2.8;e.x+=dx/d*sp*dt;e.z+=dz/d*sp*dt;e.group.position.x=e.x;e.group.position.z=e.z;e.group.position.y=height(e.x,e.z)}else{e.attack-=dt;if(e.attack<=0){e.attack=e.boss?1.45:1.75;if(d<(e.boss?4.1:2.5)&&player.invuln<=0){const harm=e.boss?19:11;health=Math.max(0,health-harm);$('#healthText').textContent=Math.ceil(health)+' / 100';$('#healthBar').style.width=health+'%';burst(player.x,height(player.x,player.z)+1,player.z,0xdb8268,8);if(health<=0){health=100;player.x=0;player.z=25;player.stamina=100;hero.position.set(0,height(0,25),25);for(const w of enemies)if(w.alive){w.x=w.boss?-0:w.x;w.z=w.boss?-25:w.z}toast('THE COASTWARDEN RALLIES AT THE WAYSTATION')}}}}}e.group.position.y+=Math.sin(time*3+e.x)*.018}}
function updateCamera(dt){const target=new THREE.Vector3(player.x,height(player.x,player.z)+1.2,player.z);const dist=8.2,ce=Math.cos(cameraPitch),se=Math.sin(cameraPitch);const desired=new THREE.Vector3(target.x+Math.sin(cameraYaw)*dist*ce,target.y+3.1+dist*se,target.z+Math.cos(cameraYaw)*dist*ce);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(target)}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=8*dt;p.mesh.material.opacity=Math.max(0,p.life/p.max);if(p.life<=0){world.remove(p.mesh);p.mesh.geometry.dispose();particles.splice(i,1)}}}
function updateWorld(dt){time+=dt;for(const s of shards)if(!s.got){s.group.position.y=height(s.x,s.z)+1.5+Math.sin(time*2.2+s.x)*.16;s.group.rotation.y=time*.48}beaconCrystal.rotation.y+=dt*.7;beaconCrystal.position.y=3.35+Math.sin(time*1.6)*.17;beaconRing.rotation.z+=dt*.22;beaconLight.intensity=memory>=3?2.6+Math.sin(time*3)*.5:0;for(const child of world.children){if(child.userData.flicker){child.intensity=1+Math.sin(time*5+child.position.x)*.2}}updateParticles(dt);if(mode==='play'){updatePlayer(dt);updateEnemies(dt)}updateCamera(dt);}
function renderLoop(){requestAnimationFrame(renderLoop);const dt=Math.min(.04,clock.getDelta());updateWorld(dt);renderer.render(scene,camera)}const clock=new THREE.Clock();
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}addEventListener('resize',resize);
